cat <<EOF > /home/user/dialog_branching_system/scripts/DialogPlayer.gd
extends Node
class_name DialogPlayer

@export var tree: DialogTree

signal line_shown(speaker: String, text: String, choices_labels: Array)
signal dialog_finished

var _current_id: StringName
var _flags: Dictionary = {}

func start():
	if not tree:
		return
	_current_id = tree.start_id
	_present_node()

func set_flag(name: StringName):
	_flags[name] = true

func has_flag(name: StringName) -> bool:
	return _flags.get(name, false)

func advance(choice_index: int = -1):
	var node = tree.get_node(_current_id)
	if not node:
		return

	if choice_index >= 0 and choice_index < _get_visible_choices(node.choices).size():
		var visible_choices = _get_visible_choices(node.choices)
		_current_id = visible_choices[choice_index].next_id
	elif node.choices.is_empty():
		_current_id = node.next_id
	else:
		# If choices exist but none chosen (or invalid index), stop or handle error.
		# Simplest is to just stop if we don't know where to go.
		_current_id = ""

	if _current_id.is_empty():
		dialog_finished.emit()
	else:
		_present_node()

func _present_node():
	var node = tree.get_node(_current_id)
	if not node:
		dialog_finished.emit()
		return

	var visible_choices = _get_visible_choices(node.choices)
	var labels = []
	for c in visible_choices:
		labels.append(c.label)

	line_shown.emit(node.speaker, node.text, labels)

func _get_visible_choices(choices: Array[DialogChoice]) -> Array[DialogChoice]:
	var result = []
	for c in choices:
		if c.condition_flag.is_empty() or has_flag(c.condition_flag):
			result.append(c)
	return result
EOF

